from taf.collectors import l1l2bip, tcpdump
from robot.api import logger

SHELL_SCRIPT = "/opt/wts/latest/sosReport_ASIL/airphone_mirror.sh"
PYTHON_SCRIPT = "/opt/wts/latest/sosReport_ASIL/gnbMirroring.py"


class L1L2Collector:

    def __init__(self):
        self.collector_name = "l1l2collector"
        self.collector = l1l2bip.l1l2bip()

    def _create_collector(self):

        tcpdump_obj = tcpdump.tcpdump()
        scripts = [SHELL_SCRIPT, PYTHON_SCRIPT]

        ap_details = {
            "host": "192.168.200.1",
            "user": "toor4nsn",
            "password": "oZPS0POrRieRtu"
        }

        try:
            tcpdump_obj.create_tcpdump_collector(
                name='tcpdump',
                options='-i any',
                executor=ap_details)
        except Exception as e:
            logger.warn('Exception raised when creating tcpdump collector: {}'.format(e))

        try:
            self.collector.create_airphone_l1l2bip_collector(
                self.collector_name,
                collector='tcpdump',
                executor=ap_details,
                script_paths=scripts)
        except Exception as e:
            logger.warn('Exception raised when creating AP L1L2 bip collector: {}'.format(e))

    def setup_and_start_collector(self):
        """
        Method used to set up and start L1L2 collector, based on TAF Collectors library.
        This method checks whether the collector already exists, and initiates it otherwise.
        If the collector object has been initiated and is up, method proceeds to set it up
        and starts collecting logs.
        """

        if not self._check_if_collector_exists():
            self._create_collector()

        if not self._check_if_collector_is_up():
            self.collector.setup(self.collector_name)
            self.collector.start_collectors(self.collector_name)

    def collect_l1l2_logs(self, output_dirpath):
        """
        Method used to stop the collector, gather logs and teardown collector object.
        If collector is working and responding correctly, this method proceeds to
        stop the collector, gather and save the logs in the provided output_dirpath
        and teardown the collector object.
        """
        if self._check_if_collector_is_up():
            self.collector.stop_collectors(self.collector_name)
            self.collector.collect_collectors(self.collector_name, output_dirpath)
            self.collector.teardown_collectors(self.collector_name)
        else:
            logger.warn('Unable to collect logs for logger {}, collector object doesn\'t respond'
                        .format(self.collector_name))

    def _check_if_collector_is_up(self):
        return self.collector.get_alias_value(self.collector_name).is_up

    def _check_if_collector_exists(self):
        return self.collector.get_alias_value(self.collector_name)
